    for b in range(0, 31):
        c = 30 - a - b
        if c < 0:
            continue
        all_distributions.append((a, b, c))

print(f"Total distributions (including permutations): {len(all_distributions)}")

# Now filter with conditions
filtered_distributions = []
for a, b, c in all_distributions:
    # At least one box has ≥ 2 coins
    if a < 2 and b < 2 and c < 2:
        continue

    # There exist two boxes whose counts differ by exactly 6
    if abs(a - b) == 6 or abs(a - c) == 6 or abs(b - c) == 6:
        filtered_distributions.append((a, b, c))

print(f"Valid distributions (including permutations): {len(filtered_distributions)}")

# Now let's get unique distributions when sorted
unique_sorted_distributions = set()
for a, b, c in filtered_distributions:
    sorted_triple = tuple(sorted([a, b, c]))
    unique_sorted_distributions.add(sorted_triple)

print(f"\nUnique distributions (sorted a≤b≤c): {len(unique_sorted_distributions)}")
print("All unique sorted distributions:")
for d in sorted(unique_sorted_distributions):
    print(f"  {d}")

# Let's verify our earlier calculation
print(f"\nOur earlier list had {len(valid_distributions)} distributions:")
for d in valid_distributions:
    print(f"  {d}")

# Check if any were missed
if set(valid_distributions) == unique_sorted_distributions:
    print("\n✓ Our distribution list is complete")
else:
    print("\n✗ Our distribution list is incomplete")
    missing = unique_sorted_distributions - set(valid_distributions)
    extra = set(valid_distributions) - unique_sorted_distributions
    if missing:
        print(f"Missing distributions: {missing}")
    if extra:
